    .then(reg => console.log('SW registered, scope:', reg.scope))
    .catch(err => console.error('SW registration failed:', err));
}
```

Notes:
- The `scope` defaults to the directory the script is served from. A worker at `/sw.js` can control the whole site; one at `/app/sw.js` only controls `/app/*`.
- Registration is idempotent — calling it again just checks for updates.
- The browser won't fetch a new version of `sw.js` more than once per 24 hours unless you force it (e.g., via `reg.update()`).
- HTTPS is required in production; `localhost` is exempted for development.

A minimal `sw.js`:

```js
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open('v1').then(cache => cache.addAll(['/', '/index.html', '/style.css']))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request).then(cached => cached || fetch(event.request))
  );
});
```
